import RNA
target = ".....((.((.((...)).((....))...)))).((.((.((...)).((....))...))))....."
unit_target = "((.((.((...)).((....))...))))"
unit_ctx_tgt = '.....'+unit_target+'...................................'

stems=[('G','C'),('C','G'),('A','U'),('U','A')]
triloops=['UUU','GAA','GUA','CUU','AAA','CAA','UGA','AGA','GAC','AUC']
tetraloops=[('G','A','A','A'),('U','U','C','G'),('G','C','A','A'),('C','U','U','G'),('A','A','A','A')]

solutions=[]
def make_unit(o1,o2,s1,s2,s3,s4,loop3,loop4):
